import React, { useState, useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import socket from '../../socket';
import './PlayerDashboard.css';

const statConfig = {
    Strength:     ['Saving Throw', 'Athletics'],
    Dexterity:    ['Saving Throw', 'Acrobatics', 'Sleight of Hand', 'Stealth'],
    Constitution: ['Saving Throw'],
    Intelligence: ['Saving Throw', 'Arcana', 'History', 'Investigation', 'Nature', 'Religion'],
    Wisdom:       ['Saving Throw', 'Animal Handling', 'Insight', 'Medicine', 'Perception', 'Survival'],
    Charisma:     ['Saving Throw', 'Deception', 'Intimidation', 'Performance', 'Persuasion']
};

const calcMod = (score) => Math.floor((score - 10) / 2);
const fmtMod  = (mod)   => (mod >= 0 ? `+${mod}` : `${mod}`);

// ─────────────────────────────────────────────
const PlayerDashboard = () => {
    const location  = useLocation();
    const navigate  = useNavigate();
    const logRef    = useRef(null);

    // ── Panel açma/kapama state ──────────────
    const [topOpen,  setTopOpen]  = useState(true);
    const [leftOpen, setLeftOpen] = useState(true);
    const [hudOpen,  setHudOpen]  = useState(true);

    // ── Karakter & Oyun ───────────────────────
    const [character,    setCharacter]    = useState(location.state?.character || null);
    const [gameCode]                      = useState(location.state?.gameCode  || 'UNKNOWN');
    const [selectedStat, setSelectedStat] = useState('Dexterity');
    const [isConnected,  setIsConnected]  = useState(false);

    // ── Log ───────────────────────────────────
    const [logs, setLogs] = useState([
        { id: 1, text: '🎲 Oturuma bağlandınız. GM bekleniyor...', type: 'info' }
    ]);

    // ── GM'den gelen veriler ──────────────────
    const [activeMapUrl,  setActiveMapUrl]  = useState(null);
    const [tokens,        setTokens]        = useState([]);
    const [combatState,   setCombatState]   = useState({ isActive: false, round: 1, currentTurnIndex: 0 });

    // ── Yardımcı: log ekle ────────────────────
    const addLog = (text, type = 'info') =>
        setLogs(prev => [...prev, { id: Date.now() + Math.random(), text, type }]);

    // ── Guard & Socket Setup ──────────────────
    useEffect(() => {
        if (!character) { navigate('/join-game'); return; }

        socket.connect();
        socket.emit('join_room', { gameCode, playerName: character.name });
        setIsConnected(true);
        addLog(`✅ "${gameCode}" odasına bağlanıldı!`, 'success');

        socket.on('log_update',     ({ text, type })       => addLog(text, type));
        socket.on('player_joined',  ({ playerName })       => addLog(`👤 ${playerName} katıldı.`, 'info'));
        socket.on('player_left',    ({ playerName })       => addLog(`👤 ${playerName} ayrıldı.`, 'info'));
        socket.on('map_changed',    ({ mapUrl })           => { setActiveMapUrl(mapUrl); addLog('🗺️ GM yeni harita açtı.', 'info'); });
        socket.on('tokens_updated', ({ tokens: t })        => setTokens(t));
        socket.on('combat_updated', ({ combatState: cs, tokens: t }) => {
            setCombatState(cs);
            setTokens(t);
            addLog(cs.isActive ? '⚔️ Savaş başladı!' : '🛡️ Savaş bitti.', cs.isActive ? 'combat' : 'info');
        });

        return () => {
            socket.emit('leave_room', { gameCode, playerName: character.name });
            ['log_update','player_joined','player_left','map_changed','tokens_updated','combat_updated']
                .forEach(ev => socket.off(ev));
            socket.disconnect();
        };
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // ── Log auto-scroll ───────────────────────
    useEffect(() => {
        if (hudOpen && logRef.current)
            logRef.current.scrollTop = logRef.current.scrollHeight;
    }, [logs, hudOpen]);

    if (!character) return null;

    // ── Hesaplamalar ──────────────────────────
    const profBonus = Math.ceil(character.level / 4) + 1;

    const getSkillBonus = (stat, skill) => {
        const mod = calcMod(character.stats[stat]);
        const prof = character.proficiencies?.[`${stat}-${skill}`] ? profBonus : 0;
        return mod + prof;
    };

    // ── Handlers ─────────────────────────────
    const handleStatChange = (field, val) =>
        setCharacter(prev => ({ ...prev, [field]: val }));

    const rollDice = (name, bonus) => {
        const roll  = Math.floor(Math.random() * 20) + 1;
        const total = roll + bonus;
        const text  = `🎲 ${character.name} – ${name}: d20(${roll}) ${fmtMod(bonus)} = ${total}`;
        addLog(text, 'dice');
        socket.emit('dice_roll', { gameCode, playerName: character.name, rollText: text, isHidden: false });
        if (!hudOpen) setHudOpen(true);
    };

    // Combat: bu oyuncunun sırası mı?
    const myIdx       = tokens.findIndex(t => t.playerId === character.id);
    const isMyTurn    = combatState.isActive && myIdx !== -1 && combatState.currentTurnIndex === myIdx;

    const logClass = (type) => ({ dice:'log-dice', success:'log-success', combat:'log-combat', damage:'log-damage', hidden:'log-hidden' }[type] || '');

    // ─────────────────────────────────────────
    return (
        <div className="pd-wrapper">

            {/* ── SENİN SIRAN UYARISI ─────────────────── */}
            {isMyTurn && <div className="pd-my-turn-alert">⚔️ SENİN SIRAN!</div>}

            {/* ═══════════════════════════════════════════
                LAYER 0 — MAP (z-index: 1)
            ═══════════════════════════════════════════ */}
            <div className="pd-layer-map">
                {activeMapUrl
                    ? <img src={activeMapUrl} alt="Harita" className="pd-game-map" />
                    : (
                        <div className="pd-board-placeholder">
                            <span className="pd-board-placeholder-icon">🗺️</span>
                            <h3>OYUN TAHTASI</h3>
                            <p>GM harita paylaşmayı bekliyor...</p>
                        </div>
                    )
                }
                {/* Token'lar (read-only) */}
                {tokens.map((token, idx) => (
                    <div
                        key={token.id}
                        className={`pd-map-token color-${token.color} ${combatState.isActive && combatState.currentTurnIndex === idx ? 'active-turn-token' : ''}`}
                        style={{ left: token.x, top: token.y, width: 50, height: 50 }}
                    >
                        {token.name && <span className="pd-token-name-tag">{token.name}</span>}
                        {token.maxHp && (
                            <div className="pd-token-hp-bar">
                                <div className="pd-token-hp-fill" style={{ width: `${Math.min(100, (token.hp / token.maxHp) * 100)}%` }} />
                            </div>
                        )}
                    </div>
                ))}
            </div>

            {/* ═══════════════════════════════════════════
                LAYER 1 — SOL SİDEBAR — Stats & Skills (z-index: 6)
            ═══════════════════════════════════════════ */}
            <div className={`pd-layer-sidebar ${leftOpen ? '' : 'closed'}`}>
                <button className="pd-sidebar-toggle-btn" onClick={() => setLeftOpen(!leftOpen)}>
                    {leftOpen ? '◀' : '▶'}
                </button>

                <div className="pd-sidebar-content">
                    <h3 className="pd-sidebar-title">STATS & SKILLS</h3>

                    {/* 6 Stat Grid */}
                    <div className="pd-attrs-grid">
                        {Object.keys(statConfig).map(stat => {
                            const mod = calcMod(character.stats[stat]);
                            return (
                                <div
                                    key={stat}
                                    className={`pd-attr-card ${selectedStat === stat ? 'selected' : ''}`}
                                    onClick={() => setSelectedStat(stat)}
                                >
                                    <span className="pd-attr-abbr">{stat.substring(0,3).toUpperCase()}</span>
                                    <span className="pd-attr-score">{character.stats[stat]}</span>
                                    <span className="pd-attr-mod">{fmtMod(mod)}</span>
                                </div>
                            );
                        })}
                    </div>

                    {/* Seçili Stat & Skill Roll */}
                    <div className="pd-skill-header">
                        <h3>{selectedStat}</h3>
                        <button
                            className="pd-roll-stat-btn"
                            onClick={() => rollDice(`${selectedStat} Kontrolü`, calcMod(character.stats[selectedStat]))}
                        >
                            🎲 {selectedStat.toUpperCase()} AT
                        </button>
                    </div>

                    {/* Skill Listesi */}
                    <div className="pd-skills-list">
                        {statConfig[selectedStat].map(skill => {
                            const bonus   = getSkillBonus(selectedStat, skill);
                            const hasProf = !!character.proficiencies?.[`${selectedStat}-${skill}`];
                            return (
                                <div
                                    key={skill}
                                    className={`pd-skill-row ${hasProf ? 'proficient' : ''}`}
                                    onClick={() => rollDice(skill, bonus)}
                                >
                                    <div className={`pd-prof-dot ${hasProf ? 'active' : ''}`} />
                                    <span className="pd-skill-name">{skill}</span>
                                    <span className="pd-skill-bonus">{fmtMod(bonus)}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* ═══════════════════════════════════════════
                LAYER 2 — SAĞ HUD — Dice Logs (z-index: 6)
            ═══════════════════════════════════════════ */}
            <div className={`pd-layer-hud ${hudOpen ? '' : 'closed'}`}>
                <button className="pd-hud-toggle-btn" onClick={() => setHudOpen(!hudOpen)}>
                    {hudOpen ? '▶' : '◀'}
                </button>

                <div className="pd-hud-content">

                    {/* Oyun kodu & bağlantı */}
                    <div className="pd-hud-code-row">
                        KOD: <span>{gameCode}</span>
                        <div className={`pd-connection-dot ${isConnected ? 'connected' : 'disconnected'}`}>
                            <div className="pd-dot" />
                            {isConnected ? 'ONLINE' : 'OFFLINE'}
                        </div>
                    </div>

                    {/* Combat sırası (sadece savaş varsa) */}
                    {combatState.isActive && tokens.length > 0 && (
                        <div className="pd-combat-order-box">
                            <div className="pd-combat-order-title">⚔️ SAVAŞ SIRASI — Tur {combatState.round}</div>
                            {tokens.map((t, idx) => (
                                <div
                                    key={t.id}
                                    className={`pd-combat-order-row ${idx === combatState.currentTurnIndex ? 'active' : ''}`}
                                >
                                    <span>{idx === combatState.currentTurnIndex ? '▶ ' : ''}{t.name || 'Anonim'}</span>
                                    <span className="pd-init-badge">{t.initiativeRoll ?? '?'}</span>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Log Ekranı */}
                    <div className="pd-log-box">
                        <div className="pd-log-box-header">
                            🎲 ZAR & LOGLAR
                        </div>
                        <div className="pd-log-scroll" ref={logRef}>
                            {logs.map(log => (
                                <div key={log.id} className={`pd-log-entry ${logClass(log.type)}`}>
                                    <span className="pd-log-time">
                                        [{new Date(log.id).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' })}]
                                    </span>
                                    <span className="pd-log-text">{log.text}</span>
                                </div>
                            ))}
                        </div>
                    </div>

                </div>
            </div>

            {/* ═══════════════════════════════════════════
                LAYER 3 — ÜST MENÜ (z-index: 10)
            ═══════════════════════════════════════════ */}
            <div className={`pd-layer-top ${topOpen ? '' : 'closed'}`}>
                <div className="pd-top-content">
                    <div className="pd-top-left">

                        <button className="pd-exit-btn" type="button" onClick={() => navigate('/main-menu')}>
                            🚪 ÇIKIŞ
                        </button>

                        <div className="pd-char-info">
                            <span className="pd-char-name">{character.name}</span>
                            <span className="pd-char-sub">Lv.{character.level} {character.charClass} • {character.species}</span>
                        </div>

                        <div className="pd-top-combat-stats">
                            {/* AC */}
                            <div className="pd-top-stat">
                                <label>AC</label>
                                <input
                                    type="number"
                                    value={character.armorClass}
                                    onChange={e => handleStatChange('armorClass', parseInt(e.target.value) || 0)}
                                />
                            </div>
                            {/* Speed */}
                            <div className="pd-top-stat">
                                <label>HIZ</label>
                                <input
                                    type="number"
                                    value={character.speed}
                                    onChange={e => handleStatChange('speed', parseInt(e.target.value) || 0)}
                                />
                            </div>
                            {/* HP */}
                            <div className="pd-top-stat">
                                <label>HP</label>
                                <div className="pd-hp-inputs">
                                    <input
                                        type="number"
                                        className="pd-hp-current"
                                        value={character.currentHp}
                                        onChange={e => handleStatChange('currentHp', parseInt(e.target.value) || 0)}
                                    />
                                    <span className="pd-hp-divider">/</span>
                                    <input
                                        type="number"
                                        value={character.maxHp}
                                        onChange={e => handleStatChange('maxHp', parseInt(e.target.value) || 0)}
                                    />
                                </div>
                            </div>
                            {/* Proficiency Bonus */}
                            <div className="pd-top-stat">
                                <label>PB</label>
                                <span className="pd-prof-val">+{profBonus}</span>
                            </div>
                            {/* Inspiration */}
                            <button
                                className={`pd-insp-btn ${character.inspiration ? 'active' : ''}`}
                                type="button"
                                onClick={() => setCharacter(prev => ({ ...prev, inspiration: !prev.inspiration }))}
                            >
                                {character.inspiration ? '🌟 İLHAM' : '⭐ İLHAM'}
                            </button>
                        </div>
                    </div>

                    {/* Savaş durumu */}
                    {combatState.isActive && (
                        <div className="pd-combat-badge">
                            <span className="pd-combat-label">⚔️ SAVAŞ</span>
                            <span className="pd-round-label">Tur {combatState.round}</span>
                        </div>
                    )}
                </div>

                {/* Aç/kapa kolu */}
                <div className="pd-top-handle" onClick={() => setTopOpen(!topOpen)}>
                    {topOpen ? '▲' : '▼'}
                </div>
            </div>

        </div>
    );
};

export default PlayerDashboard;
